"""OpenWrt Router: OpenBridge adapter (generated by `openbridge partner new`, transport filled in).

Reads an OpenWrt router over its local LuCI JSON-RPC API (auth login, then read-only ubus-style calls):
uptime, WAN state, load and the DHCP lease count. Like the Freebox integration, this adapter is
read-only by policy: there is no writable setting and no command, so nothing on the router can change.

Every value is read from the device; anything unrecognized fails closed with OpenwrtRouterError.

Status: emulator only. Record real-hardware runs in docs/DEVICE_EVIDENCE.json before claiming support.
"""
import ipaddress
import json
import urllib.error
import urllib.request

READ = {'uptime': 's', 'wan': '', 'load': '', 'dhcp_leases': ''}
WRITABLE = {}
COMMANDS = {}
POLICY = {('*', '*'): 'Router configuration is read-only in OpenBridge.',
          ('firmware', '*'): 'Firmware is never changed by OpenBridge.'}

TIMEOUT_S = 5
MAX_BODY = 262144


class OpenwrtRouterBlocked(PermissionError):
    """Refused before anything was sent."""


class OpenwrtRouterError(OSError):
    """The router could not be reached or answered something unrecognized."""


def _host_allowed(host):
    """Local network only."""
    h = (host or '').strip().lower().rstrip('.')
    if not h or '/' in h or '\\' in h or '@' in h or ' ' in h:
        return False
    try:
        ip = ipaddress.ip_address(h)
        return ip.is_private or ip.is_loopback or ip.is_link_local
    except ValueError:
        pass
    if h in ('localhost', 'openwrt'):
        return True
    if h.endswith('.lan') or h.endswith('.local'):
        return True
    return '.' not in h and h.replace('-', '').replace('_', '').isalnum()


class OpenwrtRouterTransport:
    """Minimal LuCI JSON-RPC client. Only read paths are implemented; there is no write method."""

    def __init__(self, host, username='root', password='', port=80, use_https=False, timeout=TIMEOUT_S):
        if not _host_allowed(host):
            raise OpenwrtRouterBlocked('refusing non-local router host %r' % (host,))
        self.base = '%s://%s:%d' % ('https' if use_https else 'http', host.strip(), int(port))
        self.username = username
        self.password = password
        self.timeout = timeout
        self.token = None

    def _post(self, path, payload):
        if not path.startswith('/cgi-bin/luci/rpc/'):
            raise OpenwrtRouterBlocked('refusing unexpected router path %r' % (path,))
        data = json.dumps(payload).encode()
        req = urllib.request.Request(self.base + path, data=data,
                                     headers={'Content-Type': 'application/json'}, method='POST')
        try:
            with urllib.request.urlopen(req, timeout=self.timeout) as resp:
                raw = resp.read(MAX_BODY + 1)
        except (OSError, ValueError) as e:
            raise OpenwrtRouterError('POST %s failed: %s' % (path, e)) from None
        if len(raw) > MAX_BODY:
            raise OpenwrtRouterError('POST %s answered too much' % path)
        try:
            doc = json.loads(raw.decode('utf-8'))
        except ValueError:
            raise OpenwrtRouterError('POST %s: not JSON' % path) from None
        if isinstance(doc, dict) and doc.get('error'):
            raise OpenwrtRouterError('POST %s: %s' % (path, doc['error']))
        return doc

    def login(self):
        doc = self._post('/cgi-bin/luci/rpc/auth', {'method': 'login', 'params': [self.username, self.password]})
        token = doc.get('result') if isinstance(doc, dict) else None
        if not token or not isinstance(token, str):
            raise OpenwrtRouterError('router login refused')
        self.token = token
        return token

    def call(self, obj, method, *params):
        """One authenticated read call. Only allowlisted (object, method) pairs are sent."""
        if (obj, method) not in (('sys', 'uptime'), ('sys', 'load'), ('network', 'get_wan_status'),
                                 ('dhcp', 'leases'), ('fs', 'read')):
            raise OpenwrtRouterBlocked('refusing non-read router call %s.%s' % (obj, method))
        if obj == 'fs' and (not params or params[0] != '/tmp/dhcp.leases'):
            raise OpenwrtRouterBlocked('refusing to read %r' % (params[:1],))
        if self.token is None:
            self.login()
        doc = self._post('/cgi-bin/luci/rpc/' + obj, {'method': method, 'params': [self.token, *params]})
        return doc.get('result') if isinstance(doc, dict) else None

    def read(self):
        uptime = self.call('sys', 'uptime')         # required: proves an authenticated link
        if not isinstance(uptime, (int, float)) or uptime < 0:
            raise OpenwrtRouterError('unrecognized uptime %r' % (uptime,))
        state = {'uptime': int(uptime)}

        def optional(obj, method, *params):
            try:
                return self.call(obj, method, *params)
            except OpenwrtRouterError:
                return None

        wan = optional('network', 'get_wan_status')
        if isinstance(wan, dict):
            up = wan.get('up', wan.get('is_up', wan.get('uptime')))
            state['wan'] = 'up' if (up is True or (isinstance(up, (int, float)) and up > 0)) else 'down'
        load = optional('sys', 'load')
        if isinstance(load, (list, tuple)) and load and isinstance(load[0], (int, float)):
            state['load'] = '%.2f' % load[0]
        leases = optional('dhcp', 'leases')
        if leases is None:                                  # older trees expose the lease file instead
            leases = optional('fs', 'read', '/tmp/dhcp.leases')
        if isinstance(leases, (list, tuple)):
            state['dhcp_leases'] = len(leases)
        elif isinstance(leases, str):
            state['dhcp_leases'] = sum(1 for ln in leases.splitlines() if ln.strip())
        return state

    def write(self, name, value):
        raise OpenwrtRouterBlocked(POLICY[('*', '*')])

    def command(self, name, value=None):
        raise OpenwrtRouterBlocked(POLICY[('*', '*')])


def _refusal(name, value):
    return POLICY.get((name, value)) or POLICY.get((name, '*')) or POLICY.get(('*', '*'))


class OpenwrtRouter:
    def __init__(self, transport):
        self.transport = transport
        self._before = {}

    def facts(self):
        state = self.transport.read()
        return [{'name': k, 'value': state[k], 'unit': unit} for k, unit in READ.items() if k in state]

    def set_reversible(self, name, value):
        reason = _refusal(name, value)
        if reason:
            raise OpenwrtRouterBlocked(reason)
        if name not in WRITABLE or value not in WRITABLE[name]:
            raise OpenwrtRouterBlocked('%s=%r is not an allowed setting' % (name, value))
        if name in self._before:
            raise OpenwrtRouterBlocked('this setting has a pending Undo; undo it before changing it again')
        before = self.transport.read()
        if name not in before:
            raise OpenwrtRouterBlocked('the device does not report %s' % name)
        self.transport.write(name, value)
        after = self.transport.read().get(name)
        verified = after == value
        if verified:
            self._before[name] = before[name]
        return {'setting': name, 'before': before[name], 'after': after, 'verified': verified, 'reversible': True}

    def undo(self, name):
        if name not in self._before:
            raise OpenwrtRouterBlocked('nothing to undo for %s' % name)
        target = self._before[name]
        self.transport.write(name, target)
        now = self.transport.read().get(name)
        if now == target:
            self._before.pop(name)
        return {'setting': name, 'restored': now, 'exact': now == target}

    def command(self, name, value=None):
        reason = _refusal(name, value)
        if reason:
            raise OpenwrtRouterBlocked(reason)
        if name not in COMMANDS or (COMMANDS[name] is None and value is not None) or (COMMANDS[name] is not None and value not in COMMANDS[name]):
            raise OpenwrtRouterBlocked('%s is not an allowed command' % name)
        self.transport.command(name, value)
        # Momentary commands leave no lasting state to read back: reported as executed, never as verified.
        return {'command': name, 'value': value, 'verified': None, 'reversible': False}
